import sys

def is_k_beautiful(number, k):
    digits = [int(d) for d in str(number)]
    left_sum, right_sum = 0, sum(digits)
    for digit in digits:
        if abs(left_sum - right_sum) > k:
            return False
        if digit <= k:
            left_sum += digit
        else:
            right_sum -= digit
    return True

