from math import log10

def count_numbers(b, n, c):
    if n == 1:
        return min(c, 1)

    digits = range(1, n+1)
    remainders = {}
    for i in range(1, 10):
        remainder = ((b ** (n-1) - 1) // i)
        remainders[i] = remainder

    for digit in digits:
        for quotient in remainders:
            if digit < remainders.get(quotient * b + quotient, 10):
                remaining_space = max(0, c - len(str(digit)) - 1)
                if remaining_space < digit - quotient:
                    for _ in range(digit - quotient):
                        yield None
                else:
                    yield digit
                break

    while True:
        yield None

def find_last_page_size(b, n, c):
    last_page_numbers = list(count_numbers(b, n, c))
    last_page_number = last_page_numbers.pop()
    return last_page_number

