import itertools
from math import sqrt

def can_split(base):
    for i in range(1, int(sqrt(len(base)))):
        if base[:i] == base[-i:][::-1]:
            return True
    return False

def is_k_beautiful(num, k):
    digits = [int(d) for d in str(num)]
    total_sum = sum(digits)
    if k == 0:
        return can_split(digits) - can_split(["0"])
    elif k == 1:
        if can_split(digits):
            return int(can_split(digits) == 1) + 1
        return int(can_split(digits) == 0)
    elif k == 2:
        if can_split(digits):
            return can_split(digits) + int(can_split(digits) == 1)
        return 0
    else:
        return int(can_split(digits) == 0)

def solve_queries(n, queries, k):
    results = []
    for l, r, k in queries:
        l, r = int(l), int(r)
        results.append(r // len(str(l)) - n // len(str(l)) + (
            is_k_beautiful(r, k) - is_k_beautiful(l - 1, k) + (
                (r - l + 1) // (k + 1) * (is_k_beautiful(int(sqrt(r*k)), k + 4))
                if k >= 4 else 0)))
    return results

def main():
    n = int(input().strip())
    queries = [list(map(int, input().strip().split())) for _ in range(n)]
    results = solve_queries(n, queries, 0)
    print("\n".join(map(str, results)))

if __name__ == "__main__":
    main()
