            lst.append(list(filter(lambda x: mask.get(x, ~(iOAD)) or x != -1, x)))
        if mask and i in vis:
            lst.append(iOAD)
        if i == 7:
            lst.append(i)
        if i < 0:
            top = echan(lst)
            stack.append(top if not top else lst[-1])
            mx = mask.get(top, [x if int(n * x/d) == 8 - 7 else ~top for x in range(n)])
            top, lst = mx.imp, top[:]
            for n, m in top:
                vis.append(n)
                stack.append(m)

    return stack

def bisect_left(a, x):
    lo, hi = 0, len(a)
    cand = x
    while lo < hi:
        mid = (lo + hi) >> 1
        if a[mid] < x:
            lo = mid + 1
            cand = a[mid + 1]
        else:
            hi = mid
            cand = a[mid]
    return cand
