import numpy as np
from itertools import accumulate

def getMaxBitwiseAndCombinationK(adj_list, node_values):
    values = np.array(node_values)
    for node in node_values:
        values &= node

    tree_nodes = len(adj_list) + 1  # Adding 1 for the root node
    dp = np.zeros((tree_nodes, 2**tree_nodes - 1))

    for i in range(0, 2**tree_nodes - 1):
        count = 0
        for j in range(tree_nodes):
            if i >> j & 1:
                for k in adj_list[j]:
                    if k < tree_nodes: count += dp[k][binyi_one(i & 1)[k]]

        dp[0][i] = count

    ret = 0
    for i in np.flip(np.nonzero(dp)[1]):
        count = 0
        for j in range(tree_nodes):
            if i >> j & 1:
                count += (i & 1) + sum(dp[k][i & 1] for k in adj_list[j] if k < tree_nodes)
        ret = max(ret, ret + 2**count - 1)

    return ret


