from collections import Counter

def min_merge_b(a):
    n = len(a)
    count = Counter(a)
    b = [0] * (2 * n)
    result = float('inf')

    for i in range(n):
        for j in range(i + 1, n):
            if a[i] + a[j] <= 2 * count[a[i]]:
                if i % 2 == 1:
                    b[i] += 1
                    count[a[i]] -= 1
                if j % 2 == 0:
                    b[j] += 1
                    count[a[j]] -= 1
        result = min(result, i // 2 + b.count(i // 2))
        if i % 2 == 1:
            result = min(result, j // 2 + b.count(j // 2))
        b[i // 2] += 1
        b[j // 2] += 1

    for i in range(n // 2 + 1, n):
        result = min(result, b[i])

    for i in range(n):
        result = min(result, b[i + n // 2 + 1])
        if i % 2 == 1:
            result = min(result, b[i])

    return result

