import sys

def solve(pattern, modifications):
    stack = []
    for char in pattern:
        if char == '(':
            stack.append(char)
        else:
            if not stack:
                return -1
            left = stack.pop()
            if left == '(' and char != '(':
                return -1
            if left != '(' and char != ')':
                return -1

    if not stack:
        return None
    remaining = stack.pop()

    if remaining == '(':
        cost = modifications[0][1] + modifications[-1][1]
        return cost
    elif remaining == ')':
        cost = modifications[0][0] + modifications[-1][0]
        return -1

def main():
    pattern = input().strip()

    n = int(input())

    modifications = []
    for _ in range(n):
        a, b = map(int, input().split())
        modifications.append((a, b))

    cost = solve(pattern, modifications)

    if cost == -1:
        print(-1)
    else:
        print(cost)
        for mod in modifications:
            if mod[0] == cost:
                print(mod[1], end='')
                break

if __name__ == "__main__":
    main()
