import sys

def find_max_museums(n, m, d, roads, museums_schedule):
    dp = [[0] * (n + 1) for _ in range(d + 1)]
    for city in range(n):
        dp[0][city] = 1  # Because the first day must be open

    for day in range(1, d+1):
        adjusted = '0' + '1' * (m - 1) if day > 1 else '1'
        for prev_city, next_city in roads:
            museums_from_next_city = sorted([museum for museum in museums_schedule[next_city - 1] if museum == adjusted])
            dp[day][next_city - 1] = max(dp[day][next_city - 1], sum(dp[day - 1][p_city] for p_city in museums_from_next_city))

    return max(dp[d])

