import sys

def can_execute_evil_plan(junctions, streets, query):
    # Initialize
    cycle_plan = {}
    for p in range(1, junctions + 1):
        cycle_plan[p] = set()

    # Build cycle plan
    for v in range(0, junctions - 1, 2):
        cycle_plan[v % junctions].add(v + 1)
    cycle_plan[0] = list(cycle_plan.keys())
    old_cycle_plan = cycle_plan
    for i, cycles in enumerate(old_cycle_plan):
        if i % 2 == 0:
            for c in cycles:
                if (c):
                    cycle_plan[c[0]].remove(c)
                    cycle_plan[c[1]].remove(c)

    # Process queries
    ans = []
    for i in range(query):
        ans.append("NO")
        l, r = query[i]
        if overlap(l, r, junctions, streets):
            for s in range(l - 1, r):
                c1 = get_cycle_ends(streets, junctions, s)
                if c1[0]:
                    ans[-1] = "YES"
                    break
        else:
            for c in range(l - 1, r):
                if any(map(lambda c: c, cycle_plan[c % junctions])) or is_cycle(s, junctions, streets):
                    ans[-1] = "YES"
                    break
            else:
                ans[-1] = "NO"
    return ans

def get_cycle_ends(streets, junctions, s):
    for i, c in enumerate(cycle_plan[s]):
        if i % 2:
            yield c

def overlap(l, r, junctions, streets):
    for c in get_cycle_ends(streets, junctions, l):
        if c and c[0] is not r:
            return True
    for c in get_cycle_ends(streets, junctions, r):
        if c and c[1] is not l:
            return True
    return False

def is_cycle(s, junctions, streets):
    return len(list(cycle_plan[s % junctions])) % 2 == 0 and len(
        list(map(lambda s2: s if s2 else s + junctions, get_cycle_ends(streets, junctions, s)))) % 2 == 0

# Main execution
