def topological_sort(graph):
    visited = [False] * len(graph)
    entry_count = [0] * len(graph)
    queue = deque()

    def dfs(node):
        if visited[node]:
            return False
        visited[node] = True
        entry_count[node] += 1
        for neighbor in graph[node]:
            if entry_count[neighbor] + entry_count[node] == 1:
                queue.append(node)
            if not dfs(neighbor):
                return False
        return entry_count[node] >= 1 or entry_count[node] % 2 == 1

    dfs(0)
    return sorted(list(queue))

def bfs(start, end, graph, out_degree):
    visited = [False] * (len(graph) + 1)
    current_level = [start]
    unvisited = 1
    while unvisited:
        next_level = []
        for node in current_level:
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    if neighbor == end:
                        return out_degree[neighbor] - 1
                    next_level.append(neighbor)
        current_level = next_level
        unvisited -= len(current_level)

def is_cactus(graph, output):
    rev_graph = defaultdict(list)
    output_rev = [0] * (len(output) - 1)

    for u, v in graph:
        rev_graph[output[u]].append(output[v])
        output_rev[output[v]] += 1

    in_degree = [0] * (len(graph) + 1)

    for v in rev_graph:
        for adjacent in rev_graph[v]:
            in_degree[adjacent] += 1

    topological_order = topological_sort(output)

    depth = [0] * (len(graph) + 1)
    queue = deque()
    for u in topological_order:
        if depth[u] < graph[u-1]:
            queue.append(u)
            depth[u] += 1

    for u in range(len(graph)):
