        if current == graph[u]:
            break
        depth[queue.popleft()] = inf
        for v in rev_graph[u]:
            depth[v] = min(depth[v], depth[u] + 1)

    for u in topological_order:
        if depth[u] > output_rev[u]:
            return False
    return True

