from math import floor, ceil

def is_k_beautiful(num, diff, k):
    """
    Returns True if num can be split into two subsets with the specified difference,
    where k is the difference and num is a 10^8 number.
    """
    dp = [True] * (diff + 1)
    dp[0] = True
    for digit in str(num):
        for i in range(diff, -1, -1):
            if i - int(digit) >= 0 and dp[i - int(digit)]:
                dp[i] = True
    return dp[diff]

def count_k_beautiful(l, r, k):
    """
    Counts the number of k-beautiful integers between l and r inclusive.
    """
    favorable = ceil((r - k - 0.5) / 10)
    if k > 0:
        favorable -= min(0, -k)
    return mid_binomial_coefficient(favorable + k, k)

def mid_binomial_coefficient(n, k, memo=dict()):
    """
    Calculates the number of ways to split a number n into k positive parts.
    """
    if k in memo:
        return memo[k]
    if k < 0 or n < 0:
        return 0
    if n == 0:
        return 1
    if k == 0 and n > 0:
        return 0
    count = mid_binomial_coefficient(n-1, k-1, memo) + mid_binomial_coefficient(n-1, k, memo)
    memo[k] = count
    return count

def solve_queries(n, qs):
    """
    Solves n queries for k-beautiful count.
    """
    for i, (l, r, k) in enumerate(qs, start=1):
        print(count_k_beautiful(r, r, k) - count_k_beautiful(l-1, r, k) if l > 0 else count_k_beautiful(r, r, k))

