def count_numbers(base, length, capacity):
    """
    Calculate the number of numbers with length 'length' and base 'base'
    that can fit on pages of capacity 'capacity' before the first page is full.

    Parameters:
    - base (int): Base of the numeral system.
    - length (int): Length of numbers.
    - capacity (int): Capacity of each page.

    Returns:
    - int: Number of numbers that can be written on the last page.
    """
    min_base = 2 ** (int(length / (base - 1)) + 1)
    if min_base * (base ** (length * (length - 1) // (base - 1))) <= capacity:
        return capacity // (base ** (length * (length - 1) // (base - 1)))
    else:
        max_base = (
            base ** ((length + 1) * (length - 1) // (base - 1) - 1) - capacity
        ) // base + 1
        return max_base ** (length * (length - 1) // (base - 1)) - (
            min_base ** (length * (length - 1) // (base - 1))
        ) - (
            max_base - 1
        ) ** (length * (length - 1) // (base - 1))

