# Function to calculate the cost of parsing a pattern with q star symbols
def calculate_cost(pattern, star_positions):
    if not pattern:
        return 0, ""

    cost, next_string = pattern[0], ""
    if pattern[0] == "?" and len(star_positions) == 1 and star_positions[0] == 0:
        cost, next_string = calculate_cost(pattern[1:], star_positions)

    if cost != -1:
        if pattern == next_string:
            next_string += ")"
        else:
            next_string = ") + " + next_string

    return cost + min(star_positions), next_string

